// src/app/payment/success/page.tsx
"use client";

import { useEffect, Suspense, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import {
  Paper,
  Title,
  Text,
  Button,
  Center,
  Loader,
  Group,
  Alert,
} from "@mantine/core";
import {
  IconCircleCheck,
  IconHome,
  IconShoppingCart,
  IconInfoCircle,
  IconRefresh,
} from "@tabler/icons-react";
import Link from "next/link";
import {
  useQuery,
  useQueryClient,
  QueryClient,
  QueryClientProvider,
} from "@tanstack/react-query"; // Importar QueryClient, QueryClientProvider
import { useAuthStore } from "../../../../store/auth.store"; // Ajusta ruta
import { creditTransactionService } from "../../../lib/services/credit-transaction.service"; // Ajusta ruta
import classes from "../payment-status-page.module.css"; // Reutilizamos el CSS

interface PurchaseStatusResponse {
  status: "pending_webhook" | "completed" | "failed" | "unknown";
  message: string;
  creditsAdded?: number;
  newBalance?: number;
}

// queryClient global para esta página si no está en un layout superior
// const queryClient = new QueryClient();
// export default function PaymentSuccessPageWrapper() {
//   return (<QueryClientProvider client={queryClient}><PaymentSuccessPage /></QueryClientProvider>);
// }
// Si (public_or_onboarding)/layout.tsx ya tiene QueryClientProvider, no necesitas el wrapper.

function SuccessContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const sessionId = searchParams.get("session_id");
  const { user, token, setUser } = useAuthStore((state) => ({
    // Necesitamos setUser para actualizar el saldo si es necesario
    user: state.user,
    token: state.token,
    setUser: state.setUser,
  }));
  const queryClient = useQueryClient(); // Obtener del provider

  const [showProcessingMessage, setShowProcessingMessage] = useState(true);

  // Query para verificar el estado de la compra
  const {
    data: purchaseStatus,
    isLoading,
    isError,
    error,
    refetch,
  } = useQuery<PurchaseStatusResponse, Error>({
    queryKey: ["purchase-status", sessionId],
    queryFn: async () => {
      if (!sessionId || !token)
        throw new Error("Información de sesión o autenticación faltante.");
      // El servicio necesita el token para llamar al endpoint protegido
      // Necesitarías adaptar creditTransactionService para pasar el token o que apiClient lo maneje.
      // Por ahora, asumimos que apiClient lo maneja.
      return creditTransactionService.getPurchaseStatus(sessionId); // Necesitas este método en el servicio
    },
    enabled: !!sessionId && !!token, // Solo ejecuta si hay sessionId y token
    refetchInterval: (data, query) => {
      // Sigue sondeando si el estado es 'pending_webhook' o si hay error y no es un error fatal
      if (
        data?.status === "pending_webhook" ||
        (query.state.fetchFailureCount < 3 && query.state.status === "error")
      ) {
        setShowProcessingMessage(true);
        return 5000; // Reintentar cada 5 segundos
      }
      return false; // Detener sondeo si está completado o después de varios errores
    },
    refetchOnWindowFocus: false,
    staleTime: 0, // Siempre considera stale para forzar el refetch mientras sondea
    cacheTime: 1000 * 60 * 5, // 5 minutos de cache
    onSuccess: (data) => {
      if (data.status === "completed") {
        setShowProcessingMessage(false);
        notifications.show({
          // Notificación de Mantine
          title: "¡Compra Confirmada!",
          message: `Se añadieron ${data.creditsAdded} créditos. Nuevo saldo: ${data.newBalance}.`,
          color: "green",
          icon: <IconCircleCheck size={18} />,
        });
        // Actualizar el usuario en el store de Zustand con el nuevo saldo
        if (user && data.newBalance !== undefined) {
          setUser({ ...user, credits: data.newBalance }, token);
        }
        queryClient.invalidateQueries({
          queryKey: ["pwa-user-profile", user?.id],
        }); // Invalida perfil si lo usas
      } else if (data.status !== "pending_webhook") {
        setShowProcessingMessage(false); // Detener mensaje de procesamiento si no está pendiente
      }
    },
    onError: () => {
      setShowProcessingMessage(false);
    },
  });

  useEffect(() => {
    if (!sessionId) {
      console.warn(
        "Success page: No session_id found. Redirecting to dashboard."
      );
      router.replace(user ? "/dashboard" : "/login");
    }
  }, [sessionId, router, user]);

  if (!sessionId) {
    // Redirige si no hay session_id antes de intentar la query
    return (
      <Center style={{ height: "100vh" }}>
        <Loader />
        <Text ml="sm">Redirigiendo...</Text>
      </Center>
    );
  }

  const renderContent = () => {
    if (isLoading && !purchaseStatus) {
      // Carga inicial de la query
      return (
        <Center style={{ height: "200px" }}>
          <Loader />
          <Text ml="sm">Verificando estado de la compra...</Text>
        </Center>
      );
    }
    if (isError) {
      return (
        <>
          <IconAlertCircle size={60} color="var(--mantine-color-orange-6)" />
          <Title order={3} ta="center" mt="md">
            Verificación Pendiente
          </Title>
          <Text c="dimmed" size="lg" ta="center" mt="sm" mb="xl">
            Estamos verificando tu pago. Por favor, espera unos momentos.
          </Text>
          <Text size="sm" ta="center" mb="md">
            Si esta pantalla persiste, tus créditos se aplicarán pronto. Puedes
            revisar tu saldo en el dashboard.
          </Text>
          <Text size="xs" c="dimmed" ta="center" mb="xl">
            Error detalle: {error?.message}
          </Text>
        </>
      );
    }

    if (purchaseStatus?.status === "completed") {
      return (
        <>
          <IconCircleCheck size={60} color="var(--mantine-color-green-6)" />
          <Title order={2} ta="center" className={classes.title}>
            ¡Pago Exitoso y Créditos Aplicados!
          </Title>
          <Text c="dimmed" size="lg" ta="center" mt="sm" mb="xl">
            Se han añadido {purchaseStatus.creditsAdded} créditos a tu cuenta.
          </Text>
          <Text size="lg" ta="center" mb="xl" fw={500}>
            Nuevo Saldo:{" "}
            <Text span fw={700} c="blue">
              {purchaseStatus.newBalance} créditos
            </Text>
          </Text>
        </>
      );
    }

    // Si es 'pending_webhook' o un estado 'unknown'/'failed' después de algunos reintentos
    if (showProcessingMessage || purchaseStatus?.status === "pending_webhook") {
      return (
        <>
          <Loader />
          <Title order={3} ta="center" mt="md">
            Procesando tu Compra...
          </Title>
          <Text c="dimmed" size="lg" ta="center" mt="sm" mb="xl">
            Estamos confirmando tu pago con la pasarela. Esto puede tomar unos
            segundos.
          </Text>
          <Text size="sm" ta="center" mb="md">
            Tus créditos se reflejarán en tu cuenta automáticamente una vez
            confirmado. No necesitas hacer nada más.
          </Text>
          <Button
            onClick={() => refetch()}
            variant="light"
            mt="sm"
            loading={isLoading}
          >
            Verificar Estado Manualmente
          </Button>
        </>
      );
    }

    // Fallback o estado desconocido después de reintentos
    return (
      <>
        <IconInfoCircle size={60} color="var(--mantine-color-blue-6)" />
        <Title order={3} ta="center" mt="md">
          Información de la Compra
        </Title>
        <Text c="dimmed" size="lg" ta="center" mt="sm" mb="xl">
          {purchaseStatus?.message ||
            "El estado de tu compra no pudo ser determinado en este momento."}
        </Text>
        <Text size="sm" ta="center" mb="md">
          Revisa tu saldo de créditos en el dashboard en unos minutos.
        </Text>
      </>
    );
  };

  return (
    <Paper
      withBorder
      shadow="xl"
      p={30}
      radius="md"
      className={classes.statusCard}
    >
      {renderContent()}
      <Group justify="center" mt="xl">
        {user ? ( // Verifica si user existe antes de acceder a sus propiedades
          <Button
            component={Link}
            href="/dashboard"
            leftSection={<IconHome size={18} />}
            variant="outline"
          >
            Ir a mi Dashboard
          </Button>
        ) : (
          <Button
            component={Link}
            href="/login"
            leftSection={<IconHome size={18} />}
            variant="outline"
          >
            Iniciar Sesión
          </Button>
        )}
        <Button
          component={Link}
          href="/credits"
          leftSection={<IconShoppingCart size={18} />}
        >
          Comprar más Créditos
        </Button>
      </Group>
    </Paper>
  );
}

// Necesitas envolver la página en Suspense si usas useSearchParams directamente en el componente de página
export default function PaymentSuccessPage() {
  return (
    <Suspense
      fallback={
        <Center style={{ height: "100vh" }}>
          <Loader />
        </Center>
      }
    >
      <SuccessContent />
    </Suspense>
  );
}
